import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import * as sass from 'sass';

const source = new URL('../src/keycloak/login.scss', import.meta.url);
const output = new URL('../../docker/keycloak/themes/markethub/login/resources/', import.meta.url);
const fontPackage = new URL(
  '../node_modules/@fontsource-variable/plus-jakarta-sans/',
  import.meta.url
);
const css = sass.compile(fileURLToPath(source), { charset: false }).css;
const files = [
  [
    'css/login.css',
    Buffer.from(
      '/* Generated by npm run build:keycloak-theme. Edit frontend/src/keycloak/login.scss. */\n' +
        css
    ),
  ],
  [
    'fonts/plus-jakarta-sans-latin-wght-normal.woff2',
    await readFile(new URL('files/plus-jakarta-sans-latin-wght-normal.woff2', fontPackage)),
  ],
  ['fonts/LICENSE', await readFile(new URL('LICENSE', fontPackage))],
];

for (const [name, content] of files) {
  const target = new URL(name, output);
  if (process.argv.includes('--check')) {
    const existing = await readFile(target).catch(() => null);
    if (!existing?.equals(content))
      throw new Error(`Keycloak theme is stale: ${name}. Run npm run build:keycloak-theme.`);
  } else {
    await mkdir(new URL('.', target), { recursive: true });
    await writeFile(target, content);
  }
}
console.log(
  process.argv.includes('--check') ? 'Keycloak theme is current.' : 'Keycloak theme built.'
);
